-- Initial Phase 1 schema. Use `prisma migrate dev` locally to apply it.
CREATE TYPE "RoleName" AS ENUM ('STUDENT','MENTOR','CONTENT_EDITOR','MODERATOR','SUPPORT','ADMIN','SUPER_ADMIN');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"phone" TEXT UNIQUE,"passwordHash" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Role" ("id" TEXT PRIMARY KEY,"name" "RoleName" NOT NULL UNIQUE);
CREATE TABLE "UserRole" ("userId" TEXT NOT NULL,"roleId" TEXT NOT NULL,PRIMARY KEY("userId","roleId"));
CREATE TABLE "RefreshSession" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "StudentProfile" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE,"fullName" TEXT NOT NULL,"targetExamYear" INTEGER,"classLevel" TEXT,"preferredLanguage" TEXT NOT NULL DEFAULT 'en',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Exam" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"displayOrder" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Subject" ("id" TEXT PRIMARY KEY,"examId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"displayOrder" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("examId","slug"));
CREATE TABLE "AcademicClass" ("id" TEXT PRIMARY KEY,"subjectId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"displayOrder" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("subjectId","slug"));
CREATE TABLE "Chapter" ("id" TEXT PRIMARY KEY,"classId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"displayOrder" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("classId","slug"));
CREATE TABLE "Topic" ("id" TEXT PRIMARY KEY,"chapterId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"displayOrder" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("chapterId","slug"));
CREATE TABLE "Subtopic" ("id" TEXT PRIMARY KEY,"topicId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"displayOrder" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("topicId","slug"));
ALTER TABLE "UserRole" ADD FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "UserRole" ADD FOREIGN KEY ("roleId") REFERENCES "Role"("id") ON DELETE CASCADE; ALTER TABLE "RefreshSession" ADD FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "StudentProfile" ADD FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "Subject" ADD FOREIGN KEY ("examId") REFERENCES "Exam"("id"); ALTER TABLE "AcademicClass" ADD FOREIGN KEY ("subjectId") REFERENCES "Subject"("id"); ALTER TABLE "Chapter" ADD FOREIGN KEY ("classId") REFERENCES "AcademicClass"("id"); ALTER TABLE "Topic" ADD FOREIGN KEY ("chapterId") REFERENCES "Chapter"("id"); ALTER TABLE "Subtopic" ADD FOREIGN KEY ("topicId") REFERENCES "Topic"("id");
